import os
from pydub import AudioSegment

def convert_mp3_to_ogg(source_dir, dest_folder):
    for root, dirs, files in os.walk(source_dir):
        for file in files:
            if file.endswith('.mp3'):
                mp3_file_path = os.path.join(root, file)
                ogg_file_name = file.replace('.mp3', '.ogg')
                dest_ogg_file_path = os.path.join(dest_folder, ogg_file_name)

                try:
                    sound = AudioSegment.from_mp3(mp3_file_path)
                    sound.export(dest_ogg_file_path, format=""ogg"")
                except Exception as e:
                    print(f""Error converting {mp3_file_path}: {str(e)}"")

if __name__ == ""__main__"":
    source_dir = input(""Enter the directory path: "")
    dest_folder = input(""Enter the destination folder path: "")

    convert_mp3_to_ogg(source_dir, dest_folder)
