import networkx as nx
import random

def generate_random_graph(num_nodes=None):
    if num_nodes is None:
        num_nodes = random.randint(1, 20)

    G = nx.gnm_random_graph(num_nodes, random.randint(0, num_nodes*(num_nodes-1)//2), seed=None)

    labels = {}
    for node in G.nodes():
        labels[node] = str(random.randint(0,100))

    edge_weights = {}
    for edge in G.edges():
        edge_weights[edge] = round(random.uniform(0.0, 10.0), 2)

    return G, labels, edge_weights']",77,[0],[],True,0,0,0,

