class JSONHandler:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory_func):
        if isinstance(id, str) and callable(factory_func):
            self.registry[id] = factory_func
        else:
            raise ValueError(""Invalid factory function or ID"")

    def from_json(self, json_str):
        try:
            data = json.loads(json_str)
            return self.from_dict(data)
        except json.JSONDecodeError as e:
            raise ValueError(f""Invalid JSON: {e}"")

    def to_json(self, obj):
        if isinstance(obj, dict):
            return json.dumps(obj)
        else:
            raise ValueError(""Object is not a dictionary"")

    def from_dict(self, data):
        id = data.get('id')
        if id in self.registry:
            return self.registry[id](data)
        else:
            raise ValueError(f""Unknown class ID: {id}"")
