import hashlib
import os
from cryptography.fernet import Fernet

def compute_md5_hash(file_path, chunk_size=65536):
    hasher = hashlib.md5()
    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""""):
            hasher.update(chunk)
    return hasher.hexdigest()

def validate_hash(file_path, provided_hash):
    computed_hash = compute_md5_hash(file_path)
    if computed_hash == provided_hash:
        return True
    else:
        return False

def encrypt_data(data):
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)
    encrypted_data = cipher_suite.encrypt(data.encode())
    return encrypted_data.decode()

def process_files_and_validate(files_list, verbose=False):
    for file_path in files_list:
        provided_hash = input(f""Enter the MD5 hash for {file_path}: "")
        if validate_hash(file_path, provided_hash):
            print(f""{file_path} hash matches!"")
        else:
            if verbose:
                print(f""{file_path} hash does not match. Computed hash: {compute_md5_hash(file_path)}"")
