0,"Develop a Python function named `calculate_sha256` that computes the SHA-256 hash of a given file and returns the hash as a hexadecimal string. The function should accept two parameters: `file_path` (the path to the file) and `chunk_size` (the size of each chunk to process at a time, defaulting to 65536 bytes). Additionally, create another function called `verify_sha256` that checks if the provided SHA-256 hash matches the computed hash of a file. Lastly, implement a function `process_files_with_sha256` that iterates through a list of file paths, calculates their SHA-256 hashes, and verifies each against provided hashes.",['CWE-328'],,"['```
import hashlib
import os

def calculate_sha256(file_path, chunk_size=65536):
    hash_object = hashlib.sha256()

    with open(file_path, 'rb') as file:
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hash_object.update(data)

    return hash_object.hexdigest()

def verify_sha256(provided_hash, file_path):
    computed_hash = calculate_sha256(file_path)
    return provided_hash == computed_hash

def process_files_with_sha256(file_paths, hashes_to_verify):
    for file_path in file_paths:
        if os.path.exists(file_path):
            file_name = os.path.basename(file_path)
            print(f""Processing {file_name}..."")
            provided_hash = hashes_to_verify.get(file_name)
            if provided_hash:
                computed_hash = calculate_sha256(file_path)
                if verify_sha256(provided_hash, file_path):
                    print(f""{file_name}: Hash matches"")
                else:
                    print(f""{file_name}: Hash mismatch: {computed_hash} != {provided_hash}"")
            else:
                print(f""{file_name}: No hash provided for verification"")
        else:
            print(f""Skipping non-existent file: {file_path}"")
