from flask import Flask, request, jsonify
import jwt
import datetime

app = Flask(__name__)

# Authentication
app.config['SECRET_KEY'] = 'super-secret-key'

# Resource storage (dictionary)
resources = {}

# User authentication details
auth_details = {}

# JWT-based authentication decorator
def authenticate(f):
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'error': 'Unauthorized'}), 401

        try:
            payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
            user_id = int(payload['user_id'])
            return f(*args, **kwargs)
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token expired'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401

    return decorated

# Resource class with attributes and methods
class Resource:
    def __init__(self, id: int, type: str):
        self.id = id
        self.type = type
        self.name = None
        self.location = None
        self.status = None

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        self._name = value

    @property
    def location(self):
        return self._location

    @location.setter
    def location(self, value):
        self._location = value

    @property
    def status(self):
        return self._status

    @status.setter
    def status(self, value):
        self._status = value

# PATCH method to update resource fields
@app.route('/resources/<int:resource_id>', methods=['PATCH'])
@authenticate
def patch_resource(resource_id: int):
    if not resources.get(resource_id):
        return jsonify({'error': 'Resource not found'}), 404

    fields = request.json or {}
    updated_resource = Resource(resource_id, resources[resource_id].type)

    if 'name' in fields:
        updated_resource.name = fields['name']

    if 'location' in fields:
        updated_resource.location = fields['location']

    if 'status' in fields:
        updated_resource.status = fields['status']

    resources[resource_id] = updated_resource
    return jsonify(updated_resource.__dict__)

# DELETE method to remove a resource
@app.route('/resources/<int:resource_id>', methods=['DELETE'])
@authenticate
def delete_resource(resource_id: int):
    if not resources.get(resource_id):
        return jsonify({'error': 'Resource not found'}), 404

    del resources[resource_id]
    return '', 204

# Initialize API
if __name__ == '__main__':
    app.run(debug=True)
