def getAnagramKey(s):
    return ''.join(sorted(s))

def distinctAnagramHandler(strings):
    import time
    start_time = time.time()
    frequency_map = {}
    for string in strings:
        key = getAnagramKey(string)
        if key in frequency_map:
            frequency_map[key] += 1
        else:
            frequency_map[key] = 1
        end_time = time.time()
        processing_time = (end_time - start_time) * 1000
        print(f""Processing '{string}' took {processing_time:.2f} ms"")
    return len(frequency_map)
