import pika
import time
from threading import Thread

class MessageQueue:
    def __init__(self):
        self.connection = None
        self.channel = None
        self.consumer_tag = None

    def connect(self):
        try:
            self.connection = pika.BlockingConnection(
                pika.ConnectionParameters('localhost'))
            self.channel = self.connection.channel()
        except Exception as e:
            print(f""Error connecting to RabbitMQ: {e}"")

    def publish_message(self, message):
        if not self.channel:
            self.connect()

        try:
            self.channel.basic_publish(exchange='',
                                         routing_key='messages',
                                         body=message)
        except pika.exceptions.AmqpConnectionError as e:
            print(f""Error publishing message: {e}"")
        except Exception as e:
            print(f""Error publishing message: {e}"")

    def consume_message(self):
        if not self.channel:
            self.connect()

        try:
            self.consumer_tag = self.channel.basic_consume(
                queue='messages',
                on_message_callback=self.on_message,
                auto_ack=True)
        except pika.exceptions.AmqpConnectionError as e:
            print(f""Error consuming message: {e}"")
        except Exception as e:
            print(f""Error consuming message: {e}"")

    def on_message(self, ch, method_frame, body):
        try:
            # Process the message
            print(f""Received message: {body.decode()}"")
        except Exception as e:
            print(f""Error processing message: {e}"")

    def start_consuming(self):
        while True:
            self.consume_message()
            time.sleep(1)

    def run(self):
        producer_thread = Thread(target=self.start_producer)
        consumer_thread = Thread(target=self.start_consuming)
        producer_thread.start()
        consumer_thread.start()

    def start_producer(self):
        try:
            for i in range(10):
                self.publish_message(f""Hello, {i}!"")
                time.sleep(1)
        except Exception as e:
            print(f""Error producing messages: {e}"")

if __name__ == '__main__':
    message_queue = MessageQueue()
    message_queue.run()

