class Image:
    def __init__(self, path):
        self.path = path
        self.in_use = False

    def release(self):
        self.in_use = False

def ImageLoader(image_path, config_file):
    try:
        image = Image(image_path)

        if not image.in_use:
            image.release()
            image.in_use = None

        default_dir = ''
        with open(config_file, 'r') as f:
            for line in f:
                if 'default_image_dir' in line:
                    default_dir = line.split('=')[1].strip()
                    break

        if not default_dir:
            default_dir = os.path.join(os.getenv('USERPROFILE'), 'Pictures')

        cache_dir = os.path.join(default_dir, 'cache')
        try:
            with open(os.path.join(cache_dir, image_path), 'rb') as f:
                image_data = f.read()
        except FileNotFoundError:
            print(f""Image {image_path} not found in cache."")
        except Exception as e:
            print(f""Error loading image: {e}"")

    except Exception as e:
        print(f""Error in ImageLoader: {e}"")

def ExtractSequenceNumber(input_file):
    try:
        with open(input_file, 'r') as f:
            lines = f.readlines()
        pattern = re.compile(r'Sequence:\s+(\d+)')
        for line in lines:
            match = pattern.match(line)
            if match:
                return int(match.group(1))
        return None
    except Exception as e:
        print(f""Error reading file or extracting sequence number: {e}"")
        return None

# Example usage:
