import os
from pydub import AudioSegment

def mp3_to_ogg(directory_path, target_folder):
    for root, dirs, files in os.walk(directory_path):
        for file in files:
            if file.endswith("".mp3""):
                mp3_file_path = os.path.join(root, file)
                ogg_file_name = os.path.splitext(file)[0] + "".ogg""
                ogg_file_path = os.path.join(target_folder, ogg_file_name)

                try:
                    audio = AudioSegment.from_mp3(mp3_file_path)
                    audio.export(ogg_file_path, format=""ogg"")
                except Exception as e:
                    print(f""Error converting {mp3_file_path}: {str(e)}"")

if __name__ == ""__main__"":
    directory_path = input(""Enter the directory path: "")
    target_folder = input(""Enter the target folder: "")

    mp3_to_ogg(directory_path, target_folder)
