from typing import Any, Dict

def validate_json(json_str: str) -> bool:
    try:
        json.loads(json_str)
        return True
    except ValueError:
        return False

def convert_to_dataframe(json_str: str) -> pd.DataFrame:
    if not validate_json(json_str):
        raise ValueError(""Invalid JSON input"")

    parsed_data = json.loads(json_str)

    if ""type"" in parsed_data and parsed_data[""type""] == ""array"":
        df = pd.json_normalize(parsed_data)
    else:
        try:
            df = pd.json_normalize({f""record_{i}"": item for i, item in enumerate(parsed_data, 1)})
        except TypeError as e:
            raise ValueError(""Failed to parse JSON data"") from e

    return df

def filter_dataframe(df: pd.DataFrame, condition: Dict[str, Any]) -> pd.DataFrame:
    if not condition:
        return df

    filtered_df = df[df.apply(lambda row: all(row[filter_key] == filter_value for (filter_key, filter_value) in condition.items()), axis=1)]

    return filtered_df

def save_dataframe(df: pd.DataFrame, file_path: str):
    df.to_csv(file_path)

def process_large_file(file_path: str, num_processes: int = 4, output_file: str = ""output.csv""):
    with multiprocessing.Pool(processes=num_processes) as pool:
        json_data_list = pool.map(json.load, [open(file_path, 'r')])

    try:
        df = pd.concat([convert_to_dataframe(json_str).set_index('record_1') for json_str in json_data_list])
        filtered_df = filter_dataframe(df, {""column_name"": ""value""})
        save_dataframe(filtered_df, output_file)

        print(""Processing complete."")

    except Exception as e:
        print(f""Error processing file: {e}"")
