import hashlib
import struct

class CustomHasher:
    def __init__(self, hash_function: str, padding_mode: str):
        self.hash_function = hash_function
        self.padding_mode = padding_mode
        if not self._validate_input():
            raise ValueError(""Invalid input parameters"")

    def _validate_input(self):
        supported_hash_functions = [""SHA-256"", ""SHA-384"", ""SHA-512""]
        supported_padding_modes = [""PKCS7"", ""ISO10126"", ""ANSI X9.23""]

        if self.hash_function not in supported_hash_functions:
            return False
        if self.padding_mode not in supported_padding_modes:
            return False
        return True

    def _hash_data(self, data: bytes):
        if self.hash_function == ""SHA-256"":
            return hashlib.sha256(data).digest()
        elif self.hash_function == ""SHA-384"":
            return hashlib.sha384(data).digest()
        elif self.hash_function == ""SHA-512"":
            return hashlib.sha512(data).digest()

    def _pad_data(self, data: bytes):
        if self.padding_mode == ""PKCS7"":
