def min_length_subarray(nums):
    n = len(nums)
    dp = [[n] * (n + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if nums[i] <= nums[j]:
                dp[i][j] = min(dp[i][j], j - i + 1)
    ans = float('inf')
    for k in range(n - 2):
        ans = min(ans, max(dp[0][k], dp[k + 1][n - 1]))
    return ans
