import random
from ipaddress import IPv4Address, IPv4Network

def generate_packet_headers(
    source_address_range: tuple, 
    destination_address_range: tuple, 
    protocol_values: list, 
    tcp_probability: float, 
    udp_probability: float, 
    batch_size: int
):
    if not (0 <= tcp_probability <= 1 and 0 <= udp_probability <= 1):
        raise ValueError(""Probabilities must sum up to approximately 1"")

    for rng in [source_address_range, destination_address_range]:
        if len(rng) != 2 or not all(isinstance(net, IPv4Network) for net in rng):
            raise ValueError(""Invalid IP address range"")

    for value in protocol_values:
        if not isinstance(value, int) or not 1 <= value <= 255:
            raise ValueError(""Protocol values must be integers between 1 and 255"")

    headers = []
    batch_headers = []

    try:
        while len(headers) < batch_size:
            source_ip = str(IPv4Address(random.randint(rng[0].start, rng[0].stop)))
            dest_ip = str(IPv4Address(random.randint(rng[1].start, rng[1].stop)))
            protocol = random.choice(protocol_values)
            if random.random() < tcp_probability / (tcp_probability + udp_probability):
                protocol_type = 'TCP'
            else:
                protocol_type = 'UDP'

            batch_headers.append({
                'Source Address': source_ip,
                'Destination Address': dest_ip,
                'Protocol Identifier': protocol,
                'Protocol Type': protocol_type
            })

        headers.extend(batch_headers)

    except Exception as e:
        raise ValueError(""Error generating packet headers: {}"".format(e))

    finally:
        del batch_headers[:]

    return headers
