from Crypto.PublicKey import RSA
from Crypto.Util.number import inverse
import time
import getpass
import hashlib
import os

def prompt_and_validate_key_size():
    while True:
        try:
            size = int(input(""Enter desired key size: ""))
            if size <= 0:
                print(""Key size must be a positive integer."")
            else:
                return size
        except ValueError:
            print(""Invalid input! Please enter a positive integer."")

def generate_rsa_key_pair(custom_params=None):
    if custom_params is None:
        custom_params = {}

    key_size = prompt_and_validate_key_size()

    public_exponent = 65537
    private_exponent = inverse(2, 3)

    rsa_keypair = RSA.generate(key_size, public_exponent=public_exponent, private_exponent=private_exponent, **custom_params)

    return rsa_keypair

def write_key(rsa_key, filename):
    with open(filename, 'wb') as f:
        f.write(rsa_key.export_key())

def generate_multiple_key_pairs():
    num_keys = int(input(""Enter the number of key pairs to generate: ""))

    for i in range(num_keys):
        print(f""Generating key pair {i+1}..."")
        custom_params = {""public_exponent"": 3, ""private_exponent"": 17}
        rsa_keypair = generate_rsa_key_pair(custom_params)
        write_key(rsa_keypair, f""key{i+1}.pem"")

def validate_keys(public_key, private_key):
    try:
        decrypted_text = RSA.import_key(private_key).decrypt(os.urandom(128))
        encrypted_text = RSA.import_key(public_key).encrypt(decrypted_text)
        return True
    except Exception as e:
        print(f""Error: {e}"")
        return False

def main_menu():
    while True:
        print(""\nRSA Key Generator"")
        print(""1. Generate key pair"")
        print(""2. Save private key to file"")
        print(""3. Validate key pair"")
        print(""4. Exit"")

        choice = input(""Choose an option: "")

        if choice == ""1"":
            custom_params = {""public_exponent"": 65537, ""private_exponent"": inverse(2, 3)}
            rsa_keypair = generate_rsa_key_pair(custom_params)
            write_key(rsa_keypair, ""key.pem"")
        elif choice == ""2"":
            filename = input(""Enter the filename to save private key: "")
            try:
                with open(filename, 'rb') as f:
                    private_key = f.read()
            except FileNotFoundError:
                print(f""File '{filename}' not found."")
                continue
            write_key(private_key, filename)
        elif choice == ""3"":
            public_key = input(""Enter the public key: "")
            private_key = input(""Enter the private key: "")
            if validate_keys(public_key.encode(), private_key.encode()):
                print(""Key pair is valid!"")
            else:
                print(""Key pair is not valid."")
        elif choice == ""4"":
            print(""Exiting..."")
            break
        else:
            print(""Invalid option. Please choose again."")

if __name__ == ""__main__"":
    main_menu()
