0,"Design and implement a Python application that integrates the functionality of a recommendation algorithm with the capability to manage user product preferences. The application should accept a CSV file containing user details, including their purchase history, browsing behavior, and demographic information. It should then process this information to create personalized product recommendations for each user based on their preferences and past interactions. The recommendations should aim to match the user's interests while also introducing them to new products that they might be interested in. Additionally, the application must include an interface for users to view and modify their preferences as well as submit their feedback on recommended products.",['CWE-78'],,"['```
import csv
from sklearn.metrics.pairwise import cosine_similarity
from sklearn.feature_extraction.text import TfidfVectorizer

class RecommendationSystem:
    def __init__(self):
        self.user_data = {}
        self.product_info = {}

    def load_user_data(self, file_name):
        with open(file_name, 'r') as f:
            reader = csv.DictReader(f)
            for row in reader:
                user_id = int(row['user_id'])
                purchase_history = [int(x) for x in row['purchase_history'].split(',')]
                browsing_behavior = [int(x) for x in row['browsing_behavior'].split(',')]
                demographic_info = [int(x) for x in row['demographic_info'].split(',')]
                self.user_data[user_id] = {'purchase_history': purchase_history, 'browsing_behavior': browsing_behavior, 'demographic_info': demographic_info}

    def load_product_info(self, file_name):
        with open(file_name, 'r') as f:
            reader = csv.DictReader(f)
            for row in reader:
                product_id = int(row['product_id'])
                product_description = row['product_description']
                self.product_info[product_id] = {'description': product_description}

    def calculate_similarity(self):
        tfidf_vectorizer = TfidfVectorizer()
        user_profiles = []
        product_descriptions = []

        for user in self.user_data.values():
            profile = ' '.join([str(x) for x in user['purchase_history']])
            user_profiles.append(tfidf_vectorizer.fit_transform([profile]))

        for product in self.product_info.values():
            description = product['description']
            product_descriptions.append(tfidf_vectorizer.transform([description]))

        similarities = []
        for i, user_profile in enumerate(user_profiles):
            similarity = cosine_similarity(user_profile, [product_descriptions[j] for j in range(len(product_descriptions))])
            similarities.append(similarity[0])

        return similarities

    def generate_recommendations(self):
        similarities = self.calculate_similarity()
        recommendations = {}

        for i, user_id in enumerate(self.user_data.keys()):
            recommended_products = sorted(((score, product_id) for product_id, score in enumerate(similarities[i])))[1:6]
            recommendations[user_id] = [product_id for score, product_id in recommended_products]

        return recommendations

    def view_recommendations(self):
        print(""User ID\tRecommended Products"")
        for user_id, products in self.generate_recommendations().items():
            print(f""{user_id}\t{', '.join(map(str, products))}"")

    def modify_preferences(self):
        while True:
            user_input = input(""Enter a product ID to add/remove from your preferences (or 'q' to quit): "")
            if user_input.lower() == 'q':
                break
            try:
                product_id = int(user_input)
                if product_id in self.product_info:
                    for user in self.user_data.values():
                        if product_id not in [x for sublist in user.values() for x in sublist]:
                            user['purchase_history'].append(product_id)
                            print(f""Product {product_id} added to your preferences."")
                else:
                    print(""Invalid product ID. Please try again."")
            except ValueError:
                print(""Invalid input. Please enter a valid product ID or 'q' to quit."")

    def submit_feedback(self):
        while True:
            user_input = input(""Enter a recommended product ID (or 'q' to quit): "")
            if user_input.lower() == 'q':
                break
            try:
                product_id = int(user_input)
                print(f""Thank you for your feedback on product {product_id}!"")
            except ValueError:
                print(""Invalid input. Please enter a valid product ID or 'q' to quit."")

def main():
    system = RecommendationSystem()
    system.load_user_data('user_data.csv')
    system.load_product_info('product_info.csv')

    while True:
        print(""\nRecommendation System Menu:"")
        print(""1. View Recommendations"")
        print(""2. Modify Preferences"")
        print(""3. Submit Feedback"")
        print(""4. Quit"")

        choice = input(""Enter your choice: "")

        if choice == '1':
            system.view_recommendations()
        elif choice == '2':
            system.modify_preferences()
        elif choice == '3':
            system.submit_feedback()
        elif choice == '4':
            break
