import struct

class Packet:
    def __init__(self, src_addr, dst_addr, packet_type, payload_size, seq_num):
        self.src_addr = src_addr
        self.dst_addr = dst_addr
        self.packet_type = packet_type
        self.payload_size = payload_size
        self.seq_num = seq_num

class PacketGenerator:
    def __init__(self, protocol_spec):
        self.protocol_spec = protocol_spec

    def generate_packet(self, packet_type, src_addr, dst_addr, payload_size, seq_num):
        packet = Packet(src_addr, dst_addr, packet_type, payload_size, seq_num)
        return packet

    def validate_packet(self, packet):
        if packet.packet_type not in self.protocol_spec:
            return False
        if len(packet.src_addr) != 4 or len(packet.dst_addr) != 4:
            return False
        if packet.payload_size > 1024:
            return False
        if packet.seq_num < 0:
            return False
        return True

    def create_checksum(self, packet):
        # Custom checksum algorithm implementation
        checksum = 0
        for i in range(packet.payload_size):
            checksum += packet.payload[i]
        return checksum

class ProtocolSpec:
    def __init__(self, connection_establishment_packet, data_transfer_packet, error_notification_packet):
        self.connection_establishment_packet = connection_establishment_packet
        self.data_transfer_packet = data_transfer_packet
