import os
from pydub import AudioSegment
import ffmpeg

def convert_mp3_to_ogg(directory_path, target_folder):
    for filename in os.listdir(directory_path):
        if filename.endswith("".mp3""):
            mp3_file = os.path.join(directory_path, filename)
            new_filename = filename.replace("".mp3"", "".ogg"")
            ogg_file = os.path.join(target_folder, new_filename)

            try:
                sound = AudioSegment.from_mp3(mp3_file)
                sound.export(ogg_file, format=""OGG"")
            except Exception as e:
                print(f""Error converting {filename}: {str(e)}"")

if __name__ == ""__main__"":
    directory_path = input(""Enter the directory path: "")
    target_folder = input(""Enter the target folder path: "")

    convert_mp3_to_ogg(directory_path, target_folder)
