import re
import json
from collections import defaultdict

def extract_email_addresses(file_paths, save_to_json=False):
    domain_dict = defaultdict(list)

    for file_path in file_paths:
        try:
            with open(file_path, 'r') as file:
                content = file.read()

                email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
                emails = re.findall(email_pattern, content)

                for email in emails:
                    domain = email.split('@')[-1]
                    username = '@'.join(email.split('@')[:-1])
                    domain_dict[domain].append(username)
        except (FileNotFoundError, PermissionError):
            print(f""Error: Unable to open or read file {file_path}. Skipping..."")

    if save_to_json:
        with open('email_domains.json', 'w') as f:
            json.dump(dict(domain_dict), f)

    return dict(domain_dict)']",0,[0],[],True,0,0,0,

