import hashlib
import struct

class CustomHasher:
    def __init__(self):
        self.hash_functions = {
            'SHA-256': hashlib.sha256,
            'SHA-384': hashlib.sha384,
            'SHA-512': hashlib.sha512
        }
        self.padding_modes = {
            'PKCS7': self._pkcs7_padding,
            'ISO10126': self._iso10126_padding,
            'ANSI X9.23': self._ansi_x9_23_padding
        }
        self.current_hash_function = None
        self.current_padding_mode = None

    def set_hash_function(self, hash_func):
        if hash_func in self.hash_functions:
            self.current_hash_function = self.hash_functions[hash_func]
        else:
            raise ValueError('Invalid hash function')

    def set_padding_mode(self, padding_mode):
        if padding_mode in self.padding_modes:
            self.current_padding_mode = self.padding_modes[padding_mode]
        else:
            raise ValueError('Invalid padding mode')

    def _pkcs7_padding(self, data, block_size):
        padding_len = block_size - len(data) % block_size
        return data + bytes([padding_len]) * (padding_len // 1)

    def _iso10126_padding(self, data, block_size):
        # Implementation of ISO10126 padding mode
        pass

    def _ansi_x9_23_padding(self, data, block_size):
        # Implementation of ANSI X9.23 padding mode
        pass

    def stream_hash(self, data_stream, block_size):
        current_block = bytearray(block_size)
        for chunk in iter(lambda: data_stream.read(block_size), b''):
            for i in range(len(chunk)):
                current_block[i % block_size] = chunk[i]
            hash_value = self.current_hash_function(current_block).digest()
            yield hash_value
            current_block = bytearray(block_size)

    def finalize_hash(self):
        if not self.current_hash_function:
            raise ValueError('No hash function set')
        return self.current_hash_function().digest()

# Example usage:

