hasher.set_hash_function('SHA-256')
hasher.set_padding_mode('PKCS7')

with open('data_file.bin', 'rb') as file:
    for chunk in hasher.stream_hash(file, 4096):
        print(f'Processed block: {chunk.hex()}')

final_hash = hasher.finalize_hash()
print(f'Final hash: {final_hash.hex()}')
