def generate_packet_headers(source_address_range, destination_address_range, protocol_values, tcp_probability, udp_probability, batch_size):
    import random
    from ipaddress import IPv4Address, IPv4Network
    import ipaddress

    if not validate_ip_range(source_address_range) or not validate_ip_range(destination_address_range):
        raise ValueError(""Invalid IP address range"")

    if not all(isinstance(val, int) and 1 <= val <= 255 for val in protocol_values):
