    if abs(tcp_probability + udp_probability - 1) > 1e-6:
        raise ValueError(""Probability values do not sum up to approximately 1"")

    def validate_ip_range(ip_range):
        try:
            start_ip = IPv4Address(str(ip_range[0]))
            end_ip = IPv4Address(str(ip_range[1]))
            return (start_ip <= end_ip)
        except ValueError:
            return False

    packet_headers = []
    for _ in range(batch_size):
        source_addr = str(random.randint(int(IPv4Network(source_address_range).int_ip), int(IPv4Network(destination_address_range).int_ip)))
        dest_addr = str(random.randint(int(IPv4Network(source_address_range).int_ip), int(IPv4Network(destination_address_range).int_ip)))
        protocol_id = random.choice(protocol_values)

