from flask import Flask, jsonify, request
import jwt
import time
from datetime import datetime, timedelta

app = Flask(__name__)

# Database of user profiles
user_profiles = {
    ""1"": {""username"": ""admin"", ""password"": ""password123""},
    ""2"": {""username"": ""user1"", ""password"": ""user123""}
}

# JWT secret key and algorithm
SECRET_KEY = ""your_secret_key_here""
ALGORITHM = ""HS256""

def generate_token(username):
    payload = {
        ""exp"": datetime.utcnow() + timedelta(minutes=30),
        ""username"": username
    }
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)

@app.route('/login', methods=['POST'])
def login():
    if request.is_json:
        username = request.json.get('username', None)
        password = request.json.get('password', None)
        if username in user_profiles and user_profiles[username]['password'] == password:
            return {""token"": generate_token(username)}, 200
    return {""error"": ""Invalid credentials""}, 401

@app.route('/register', methods=['POST'])
def register():
    if request.is_json:
        username = request.json.get('username', None)
        password = request.json.get('password', None)
        user_profiles[username] = {""username"": username, ""password"": password}
        return {""message"": f""User {username} created successfully""}, 201

@app.route('/profiles', methods=['GET'])
@jwt_required
def get_user_profiles():
    return jsonify(user_profiles), 200

@app.route('/profile', methods=['POST'])
@jwt_required
def update_profile():
    if request.is_json:
        username = get_jwt_username()
        new_data = request.json
        user_profiles[username].update(new_data)
        # Send notification to the user
        send_notification(f""Profile updated for {username}!"")
        return {""message"": f""Profile updated successfully for {username}""}, 200

@app.route('/profile', methods=['PUT'])
@jwt_required
def update_profile():
    if request.is_json:
        username = get_jwt_username()
        new_data = request.json
        user_profiles[username].update(new_data)
        # Send notification to the user
        send_notification(f""Profile updated for {username}!"")
        return {""message"": f""Profile updated successfully for {username}""}, 200

@app.route('/profile', methods=['DELETE'])
@jwt_required
def delete_profile():
    username = get_jwt_username()
    del user_profiles[username]
    # Send notification to the user
    send_notification(f""Profile deleted for {username}!"")
    return {""message"": f""Profile deleted successfully for {username}""}, 200

def jwt_required(f):
    def decorated(*args, **kwargs):
        if 'Authorization' not in request.headers:
            return {'error': 'No token provided'}, 401
        token = request.headers['Authorization'].split(' ')[1]
        try:
            payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
            current_user = payload.get('username')
            kwargs['username'] = current_user
        except jwt.ExpiredSignatureError:
            return {'error': 'Token has expired'}, 401
        except jwt.InvalidTokenError:
            return {'error': 'Invalid token'}, 401
        return f(*args, **kwargs)
    return decorated

def send_notification(message):
    # Implementation of sending notifications goes here
    print(f""Notification sent: {message}"")

if __name__ == '__main__':
    app.run(debug=True)

