class Record:
    def __init__(self, key_size, min_key, max_key):
        self.key_size = key_size
        self.min_key = min_key
        self.max_key = max_key
        self.used_keys = set()
        self.values = []

    def populate(self):
        for _ in range(self.key_size):
            value = random.randint(0, 100)
            if value not in range(self.min_key, self.max_key + 1):
                raise ValueError(f""Value {value} is outside the key range ({self.min_key}, {self.max_key})"")
            self.values.append(value)

    def validate_unique_keys(self):
        for value in self.values:
            if value in self.used_keys:
                raise ValueError(f""Duplicate key found: {value}"")
            self.used_keys.add(value)

class RecordsArray:
