        self.records = [Record(*[random.randint(1, 10), random.randint(0, 100), random.randint(100, 200)]) for _ in range(total_records)]

    def populate(self):
        for record in self.records:
            record.populate()
            record.validate_unique_keys()

    def get_progress_tracker(self):
