    def xml_to_dict(element, parent_key=""""):
        if len(element) == 0:
            return {}
        child_dict = {}
        for child in element:
            tag_name = child.tag.split(""}"")[1].split(""}"")[-1]
            if ""children"" not in child.tag:
                child_dict[prefix + ""_"" + tag_name] = xml_to_dict(child, prefix + ""_"" + tag_name)
