import hashlib
import os

def compute_md5_hash(file_path, chunk_size=65536):
    hasher = hashlib.md5()
    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""""):
            hasher.update(chunk)
    return hasher.hexdigest()

def validate_hash(file_path, provided_hash):
    computed_hash = compute_md5_hash(file_path)
    return computed_hash == provided_hash

def process_files_and_validate(files_list, verbose=False):
    for file in files_list:
        computed_hash = compute_md5_hash(file)
        if verbose:
            print(f""Hash for {file}: {computed_hash}"")
        hash_results[file] = computed_hash
    for file, stored_hash in hash_results.items():
        validation_result = validate_hash(file, stored_hash)
        print(f""Validation result for {file}: {validation_result}"")

# Example usage:

files_to_process = [""example.txt"", ""example2.txt""]
process_files_and_validate(files_to_process)
