import requests
from flask_sqlalchemy import SQLAlchemy
from dotenv import load_dotenv

load_dotenv()

API_KEY = ""YOUR_API_KEY""
STOCK_DATA_API_URL = ""https://stock-data-api.com/api/v1/stock/prices""

def fetch_stock_prices(companies):
    try:
        headers = {""Authorization"": f""Bearer {API_KEY}""}
        params = {""companies"": "", "".join(companies)}
        response = requests.get(STOCK_DATA_API_URL, headers=headers, params=params)
        if response.status_code == 200:
            data = response.json()
            db = SQLAlchemy()
            stock_prices_table = db.Table(""stock_prices"", db.metadata,
                                           db.Column(""company"", db.String),
                                           db.Column(""price"", db.Float))

            for company in companies:
                price = next((d[""price""] for d in data if d[""company""] == company), None)
                if price is not None:
                    stock_prices_table.insert(company=company, price=price).execute()
        else:
            print(f""Error fetching stock prices: {response.status_code}"")
    except requests.exceptions.RequestException as e:
        print(f""Request failed: {e}"")

if __name__ == ""__main__"":
    fetch_stock_prices([""AAPL"", ""GOOGL"", ""MSFT""])
