import ipaddress
import random

def generate_packet_headers(source_range, dest_range, protocols, tcp_prob, udp_prob, batch):
    if not validate_ip_range(source_range) or not validate_ip_range(dest_range):
        raise ValueError(""Invalid IP address range"")

    if not all(isinstance(val, int) and 1 <= val <= 255 for val in protocols):
        raise ValueError(""Invalid protocol values"")

    if abs(tcp_prob + udp_prob - 1) > 1e-6:
        raise ValueError(""Probability values do not sum up to approximately 1"")

    def validate_ip_range(ip_range):
        try:
            start_ip = ipaddress.ip_address(str(ip_range[0]))
            end_ip = ipaddress.ip_address(str(ip_range[1]))
            return start_ip < end_ip
        except ValueError:
            return False

    packet_headers = []
    for _ in range(batch):
        source_addr = random.choice(list(range(*source_range)))
        dest_addr = random.choice(list(range(*dest_range)))
        protocol_id = random.choice(protocols)

        prob_choice = random.random()
        if prob_choice < tcp_prob:
            proto_type = 'TCP'
        elif prob_choice > (tcp_prob + udp_prob - udp_prob):
            proto_type = 'UDP'

        packet_headers.append({
            ""Source Address"": f""{source_addr}"",
            ""Destination Address"": f""{dest_addr}"",
            ""Protocol Identifier"": protocol_id,
            ""Protocol Type"": proto_type
        })

    return packet_headers']",0,[0],[],True,0,0,0,

