import json
import random
from datetime import datetime, timedelta

class WiFI BeaconGenerator:
    def __init__(self):
        self.beacons = []

    def generate_beacons(self, num_beacons: int, min_channel: int, max_channel: int,
                         min_interval: int, max_interval: int, start_time: datetime, end_time: datetime):
        for _ in range(num_beacons):
            rssi = random.randint(-80, -20)  # random RSSI value
            bssid = ""xx:xx:xx:xx:xx:xx""  # fixed BSSID
            channel = random.randint(min_channel, max_channel)
            interval = random.randint(min_interval, max_interval)
            timestamp = self.get_random_timestamp(start_time, end_time)

            beacon_data = {""BSSID"": bssid, ""Channel"": channel,
                           ""Beacon Interval"": interval, ""Timestamp"": timestamp.strftime(""%Y-%m-%d %H:%M:%S""), ""RSSI"": rssi}

            self.beacons.append(beacon_data)

    def get_random_timestamp(self, start_time: datetime, end_time: datetime):
        time_range = end_time - start_time
        random_seconds = random.randint(0, int(time_range.total_seconds()))
        return start_time + timedelta(seconds=random_seconds)

    def sort_beacons(self):
        self.beacons.sort(key=lambda x: datetime.strptime(x[""Timestamp""], ""%Y-%m-%d %H:%M:%S""))

    def to_json(self):
        return json.dumps(self.beacons)

    def check_input_validity(self, num_beacons: int, min_channel: int, max_channel: int,
                             min_interval: int, max_interval: int, start_time: datetime, end_time: datetime):
        if not isinstance(num_beacons, int) or num_beacons <= 0:
            raise ValueError(""Number of beacons must be a positive integer."")
        if not isinstance(min_channel, int) or min_channel < 1:
            raise ValueError(""Minimum channel number must be at least 1."")
        if not isinstance(max_channel, int) or max_channel < 1:
            raise ValueError(""Maximum channel number must be at least 1."")
        if not isinstance(min_interval, int) or min_interval <= 0:
            raise ValueError(""Minimum beacon interval must be a positive integer."")
        if not isinstance(max_interval, int) or max_interval <= 0:
            raise ValueError(""Maximum beacon interval must be a positive integer."")
        if start_time > end_time:
            raise ValueError(""Start time cannot be later than end time."")

    def run(self):
        num_beacons = int(input(""Enter the number of Wi-Fi beacons: ""))
        min_channel = int(input(""Enter the minimum channel number (inclusive): ""))
        max_channel = int(input(""Enter the maximum channel number (inclusive): ""))
        min_interval = int(input(""Enter the minimum beacon interval (in seconds) (inclusive): ""))
        max_interval = int(input(""Enter the maximum beacon interval (in seconds) (inclusive): ""))
        start_time_str = input(""Enter the start time (YYYY-MM-DD HH:MM:SS): "")
        end_time_str = input(""Enter the end time (YYYY-MM-DD HH:MM:SS): "")

        try:
            self.check_input_validity(num_beacons, min_channel, max_channel, min_interval, max_interval,
                                      datetime.fromisoformat(start_time_str), datetime.fromisoformat(end_time_str))

            self.generate_beacons(num_beacons, min_channel, max_channel, min_interval, max_interval,
                                  datetime.fromisoformat(start_time_str), datetime.fromisoformat(end_time_str))
            self.sort_beacons()
            print(self.to_json())
        except ValueError as e:
            print(f""Error: {str(e)}"")

if __name__ == ""__main__"":
    generator = WiFiBeaconGenerator()
    generator.run()
