def generate_gadget_list(num_gadgets: int) -> list:
    product_names = [""ProductA"", ""ProductB"", ""ProductC""]
    price_range = (10, 100)

    gadget_list = []
    for _ in range(num_gadgets):
        name = random.choice(product_names)
        price = random.randint(*price_range)
        gadget_list.append({""NAME"": name, ""PRODUCT_PRICE"": price})

    return gadget_list

def create_nfaapi_crc_indication_pdu_variant(gadget_list: list) -> dict:
    variant = {""NFAPI_CRC_INDICATION_PDU_Variant"": {}}
    for gadget in gadget_list:
        gadget_name = gadget[""NAME""]
        tag_version = random.choice(list(TagVersion))
        variant[""NFAPI_CRC_INDICATION_PDU_Variant""][gadget_name] = {""CRC_INDICATION_REL8_TAG"": tag_version}

    return variant

def generate_nfaapi_crc_indication_pdu_t(gadget_list: list) -> dict:
    nfaapi_crc_indication_pdu_t = {""RX_UE_INFORMATION_TAG"": [], ""RNTI"": []}
    for gadget in gadget_list:
        gadget_name = gadget[""NAME""]
        rx_ue_info_tag = f""RX_UE_INFO_TAG_{gadget_name}""
        rnti = random.randint(1, 100)
        nfaapi_crc_indication_pdu_t[""RX_UE_INFORMATION_TAG""].append(rx_ue_info_tag)
        nfaapi_crc_indication_pdu_t[""RNTI""].append(rnti)

    return nfaapi_crc_indication_pdu_t

def validate_nfaapi_crc_indication_pdu_t(nfaapi_crc_indication_pdu_t: dict, validate_rx_ue_info_tag=True) -> dict:
    for rx_ue_info_tag in nfaapi_crc_indication_pdu_t[""RX_UE_INFORMATION_TAG""]:
        if not 1 <= int(rx_ue_info_tag.split(""_"")[2]) <= 100:
            raise ValueError(""Invalid RX UE Information Tag"")

    for rnti in nfaapi_crc_indication_pdu_t[""RNTI""]:
        if not 1 <= rnti <= 100:
            raise ValueError(""Invalid RNTI"")

    return nfaapi_crc_indication_pdu_t

def generate_instances(num_instances: int) -> list:
    gadget_list = generate_gadget_list(num_instances)
    variant = create_nfaapi_crc_indication_pdu_variant(gadget_list)

    instances = []
    for _ in range(num_instances):
        instance = {}
        for gadget_name, tag_version in variant[""NFAPI_CRC_INDICATION_PDU_Variant""].items():
            instance[f""{gadget_name}_CRC_INDICATION_REL8_TAG""] = tag_version.value
        instances.append(instance)

    return instances

def benchmark_instance_generation(num_instances: int) -> dict:
    start_time = time.time()
    instances = generate_instances(num_instances)
    end_time = time.time()

    memory_usage = round(memory_usage_info(), 2)
    execution_time = round(end_time - start_time, 2)

    return {""Memory Usage"": memory_usage, ""Execution Time"": execution_time}

