import rsa
import threading
import time
import requests

# Function to generate RSA key pair
def generate_keypair():
    (public_key, private_key) = rsa.newkeys(2048)
    return public_key, private_key

# Function to encrypt data using the generated key pair
def encrypt_data(data, public_key):
    return rsa.encrypt(data.encode(), public_key)

# Function to start and stop the server with unpredictable delay
def manage_server(start_server_function):
    def wrapper(*args, **kwargs):
        time.sleep(round(time.time()) % 5 + 1)
        start_server_function(*args, **kwargs)
    return wrapper

# Function to send notification upon server termination
@manage_server
def notify_monitoring_system(server_running):
    if not server_running:
        requests.post('https://monitoring-system.com/termination-notification', json={'server_name': 'RSA_Server'})

# Main program function
def main():
    # Generate RSA key pair
    public_key, private_key = generate_keypair()

    # Start the server with unpredictable delay
    @manage_server
    def start_server():
        print(""Server started."")
        while True:
            # Encrypt user data using the generated key pair
            encrypted_data = encrypt_data(input(""Enter data to be encrypted: ""), public_key)
            print(f""Encrypted data: {encrypted_data}"")
            time.sleep(1)

    # Start and stop the server with unpredictable delay
    start_server()
    input(""Press Enter to terminate the server. Press Ctrl+C to interrupt."")
    notify_monitoring_system(server_running=False)

if __name__ == ""__main__"":
    main()
