import argparse
import csv
from collections import Counter
import sys

def parse_arguments():
    parser = argparse.ArgumentParser(description=""Count unique email addresses in a CSV and write results to an output file."")
    parser.add_argument(""input_csv"", type=str, help=""Path to the input CSV file"")
    parser.add_argument(""output_file"", type=str, help=""Path to the output file"")
    return parser.parse_args()

def read_csv(input_path):
    emails = set()
    try:
        with open(input_path, 'r', newline='', encoding='utf-8') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                emails.update(row['email'].split())
        return emails
    except FileNotFoundError:
        print(f""Error: File '{input_path}' not found."")
        sys.exit(1)

def write_counts(emails, output_path):
    try:
        with open(output_path, 'w', newline='', encoding='utf-8') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(['Email', 'Count'])
            for email, count in sorted(Counter(emails).items()):
                writer.writerow([email, count])
    except IOError as e:
        print(f""Error: {e}"")
        sys.exit(1)

def main():
    args = parse_arguments()

    if not args.input_csv or not args.output_file:
        sys.exit(1)

    emails = read_csv(args.input_csv)

    if not emails:
        print(""No valid email addresses found in the input CSV."")
        sys.exit(1)

    write_counts(emails, args.output_file)

if __name__ == ""__main__"":
    main()
