import requests
import json

def authenticate_user(client_id, client_secret, username, password):
    auth_url = f""https://oauth-server.com/token""
    data = {
        ""grant_type"": ""password"",
        ""username"": username,
        ""password"": password,
        ""client_id"": client_id,
        ""client_secret"": client_secret
    }

    try:
        response = requests.post(auth_url, data=data)
        if response.status_code == 200:
            access_token = json.loads(response.text)[""access_token""]
            return access_token
        else:
            raise Exception(f""Authentication failed with status code {response.status_code}"")
    except requests.exceptions.RequestException as e:
        raise Exception(""Error occurred while authenticating the user"") from e

def update_user_profile(access_token, user_id):
    profile_url = f""https://api.user-profile.com/{user_id}""
    headers = {""Authorization"": f""Bearer {access_token}""}

    try:
        response = requests.get(profile_url, headers=headers)
        if response.status_code == 200:
            return json.loads(response.text)
        else:
            raise Exception(f""Failed to retrieve profile with status code {response.status_code}"")
    except requests.exceptions.RequestException as e:
        raise Exception(""Error occurred while updating the user profile"") from e

client_id = ""your_client_id""
client_secret = ""your_client_secret""

username = ""your_username""
