# Define a class to handle MQTT client functionality
class MQTTClient:
    def __init__(self, host='localhost', port=1883):
        self.client = mqtt.Client()
        self.client.on_connect = self.on_connect
        self.client.on_disconnect = self.on_disconnect
        self.client.on_message = self.on_message

    def connect(self, client_id, username, password, keepalive=60):
        self.client.username_pw_set(username, password)
        self.client.will_set('disconnect', qos=1, retain=False)
        self.client.connect(client_id, host, port, keepalive)

    def subscribe(self, topics):
        for topic in topics:
            self.client.subscribe(topic)

    def publish(self, topic, data, retain=False):
