import os
from pydub import AudioSegment

def convert_mp3_to_ogg(directory_path, target_folder):
    for root, dirs, files in os.walk(directory_path):
        for file in files:
            if file.endswith('.mp3'):
                mp3_file = os.path.join(root, file)
                ogg_file = os.path.join(target_folder, file[:-4] + '.ogg')
                try:
                    audio_segment = AudioSegment.from_mp3(mp3_file)
                    audio_segment.export(ogg_file, format=""ogg"")
                except Exception as e:
                    print(f""Error converting {mp3_file}: {str(e)}"")

directory_path = input(""Enter the directory path: "")
target_folder = os.path.join(os.getcwd(), ""converted_files"")

if not os.path.exists(target_folder):
    os.makedirs(target_folder)

convert_mp3_to_ogg(directory_path, target_folder)
