    def __init__(self, rx_ue_information_tag, rnti):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_indication_rel8_tag = {""crcflag"": random.choice([True, False])}

def generate_crc_value(pdu):
    crc_value = 0xFFFFFFFF
    poly = 0x04C11DB7

    for byte in pdu:
        crc_value ^= byte << 24
        for _ in range(8):
            if crc_value & 0x80000000:
                crc_value <<= 1
                if crc_value & poly:
                    crc_value ^= poly << (32 - struct.bit_length(poly))
            else:
                crc_value <<= 1

    return ~crc_value & 0xFFFFFFFF

