import json
from abc import ABC, abstractmethod

class JSONableObject(ABC):
    @abstractmethod
    def to_json(self):
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, data):
        pass

class JSONObjectRegistry:
    registry = {}

    @staticmethod
    def register_object_id(id_, factory_function):
        JSONableObject.registry[id_] = factory_function

    @staticmethod
    def get_object_id(obj_type):
        return list(JSONableObject.registry.keys())[list(JSONableObject.registry.values()).index(lambda x: x.__name__ == obj_type)]

    @staticmethod
    def create_object(obj_type, data):
        factory_function = JSONableObject.registry[JSONableObject.get_object_id(obj_type)]
        return factory_function(data)

class JSONConverter:
    @classmethod
    def object_to_json(cls, obj):
        return json.dumps(obj.to_json())

    @classmethod
    def objects_from_json(cls, data):
        result = []
        for item in data:
            id_ = item['id']
            obj_type = item['type']
            instance_data = {k: v for k, v in item.items() if k not in ['id', 'type']}
            result.append(JSONableObject.registry[JSONableObject.get_object_id(obj_type)](instance_data))
        return result

