def generateImageHistogram(image):
    histogram = {}
    for row in image:
        for pixel in row:
            if isinstance(pixel, int) and (pixel >= 0 and pixel <= 255):
                if pixel not in histogram:
                    histogram[pixel] = 1
                else:
                    histogram[pixel] += 1

    total_pixels = sum(histogram.values())

    normalized_histogram = {}
