import random
import string
from datetime import date
import logging
from threading import Lock

class Book:
    def __init__(self):
        self.isbn = None
        self.title = ''
        self.author = ''
        self.year = 0
        self.lock = Lock()

    def generate_isbn(self):
        while True:
            isbn = ''.join(random.choices(string.ascii_uppercase + string.digits, k=13))
            if not used_isbns.get(isbn):
                break
        return isbn

    def verify_unique_isbn(self):
        with self.lock:
            global used_isbns
            while True:
                self.isbn = self.generate_isbn()
                if not used_isbns[self.isbn]:
                    break

def validate_input(book):
    if not isinstance(book.title, str) or len(book.title) > 255:
        logging.error(""Invalid book title. It must be a string up to 255 characters."")
        return False
    if not isinstance(book.author, str) or len(book.author.split()) > 2 or len(book.author.split()[0]) > 64 or len(book.author.split()[-1]) > 64:
        logging.error(""Invalid author name. It must be a string with first and last names separated by a space, each up to 64 characters."")
        return False
    if not isinstance(book.year, int) or book.year < 1900 or book.year > date.today().year:
        logging.error(""Invalid publication year. It must be an integer between 1900 and the current year."")
        return False
    return True

def encrypt_sensitive_info(book):
    from cryptography.fernet import Fernet
    key = Fernet.generate_key()
    f = Fernet(key)
    book.title = f.encrypt(book.title.encode())
    book.author = f.encrypt(book.author.encode())

def manage_catalog():
    used_isbns = {}
    books = []

    while True:
        print(""1. Add a new book\n2. Remove an expired book\n3. Exit"")
        choice = input(""Choose an option: "")

        if choice == '1':
            book = Book()
            book.verify_unique_isbn()
            book.title = input(""Enter the title of the book: "")
            book.author = input(""Enter the author's name: "")
            book.year = int(input(""Enter the publication year: ""))

            try:
                validate_input(book)
                if book.isbn not in used_isbns:
                    used_isbns[book.isbn] = True
                    books.append(book)
                    logging.info(f""Added new book with ISBN {book.isbn}: {book.title} by {book.author}, published in {book.year}."")
                else:
                    logging.error(""ISBN already exists. Cannot add the book."")
            except Exception as e:
                logging.error(f""Error adding book: {str(e)}"")

        elif choice == '2':
            if not books:
                print(""No expired books to remove."")
            else:
                for book in books[:]:
                    if date.today().year - book.year > 5: # Remove books that are more than 5 years old
                        with book.lock:
                            used_isbns[book.isbn] = False
                            books.remove(book)
                            logging.info(f""Removed expired book with ISBN {book.isbn}: {book.title} by {book.author}, published in {book.year}."")
        elif choice == '3':
            break

    logging.info(""Exiting the program."")
