import re
import os
from typing import Tuple, List

def process_sorted_file(filename: str) -> Tuple[bool, int, List[str]]:
    try:
        with open(filename, 'r') as f:
            lines = f.readlines()
            if not lines:
                print(""Warning: The file is empty."")
                return False, None, []

            sorted_lines = sorted(lines)
            last_line = sorted_lines[-1].strip()

            seq_pattern = r'Seq: (\d+)'
            match = re.search(seq_pattern, last_line)

            if match:
                return True, int(match.group(1)), sorted_lines
