def create_software_modules(size, modules_list):
    try:
        if size <= 0:
            raise ValueError(""Size must be greater than zero."")

        module_types = ['A', 'B', 'C']
        module_versions_ranges = {
            'A': range(1, 10),
            'B': range(11, 20),
            'C': range(21, 30)
        }
        statuses = ['Active', 'Inactive', 'Unknown']

        for i in range(size):
            if modules_list is None:
                modules_list = [SoftwareModule(f'Module {i+1}', 
                                                f'{random.choice(module_types)}_{random.randint(*module_versions_ranges[random.choice(module_types)])}',
                                                random.choice(statuses))]
            else:
