def calculate_sha256(file_path: str, chunk_size: int = 65536) -> str:
    sha256 = hashlib.sha256()
    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""""):
            sha256.update(chunk)
    return sha256.hexdigest()

def verify_sha256(computed_hash: str, expected_hash: str) -> bool:
    return computed_hash == expected_hash

def process_files_with_sha256(file_paths: List[str], hashes_dict: dict) -> Tuple[List[str], List[str]]:
    mismatched = []
    matched = []
    for file_path in file_paths:
        if not isfile(file_path):
            raise ValueError(f""File {file_path} does not exist"")
        computed_hash = calculate_sha256(file_path)
        if file_path in hashes_dict and verify_sha256(computed_hash, hashes_dict[file_path]):
            matched.append(file_path)
        else:
            mismatched.append(file_path)
    return matched, mismatched
