file_path = 'config.json'
config.load_config(file_path)
config.validate_config()

key = 'some_key'
value = config.get_config_value(key)

if value is not None:
    print(f""Config value for key '{key}': {value}"")
else:
    print(f""No value found for key '{key}'"")
