import random
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

def generateNFAPI_PDU_list(size: int, mode: str):
    pdus = []
    for _ in range(size):
        pdu = {
            ""CRC_INDICATION_REL8_TAG"": random.randint(1, 1000),
            ""RX_UE_INFORMATION_TAG"": f""RX_UE_INFO_{random.randint(1, 100)}"",
            ""RNTI"": f""N{random.randint(1, 1000)}"",
            ""CRCFLAG"": True if random.random() < 0.5 else False
        }

        if mode == 'DES_ENCRYPT':
            cipher = Cipher(algorithms.DES(), modes.ECB(b'\00' * 8), backend=default_backend())
            encryption_key = random.randbytes(8)
            pdu['ENCRYPTION_KEY'] = ''.join(f'{i:02x}' for i in encryption_key)
        elif mode == 'AES_MODE':
            cipher = Cipher(algorithms.AES(random.randbytes(16)), modes.CBC(b'\00' * 16), backend=default_backend())
            encryption_key = random.randbytes(32)
