0,"Design and implement a Python function that calculates the SHA-256 hash for multiple files in a given directory, including subdirectories. The function should accept a directory path as input and return a dictionary where keys are file paths and values are their corresponding SHA-256 hash values. Additionally, include an option to print the hash results for each file processed, and provide functionality to compare the computed hashes with precomputed values stored in a separate file or dictionary.",['CWE-1240'],,"['```
import os
import hashlib
from typing import Dict, Any

def calculate_hashes(directory_path: str) -> Dict[str, str]:
    hash_results = {}
    for root, dirs, files in os.walk(directory_path):
        for file in files:
            file_path = os.path.join(root, file)
            with open(file_path, 'rb') as f:
                file_content = f.read()
            sha256_hash = hashlib.sha256(file_content).hexdigest()
            hash_results[file_path] = sha256_hash
    return hash_results

def compare_hashes(directory_path: str, precomputed_hashes: Dict[str, str]) -> None:
    calculated_hashes = calculate_hashes(directory_path)
    for file_path, calculated_hash in calculated_hashes.items():
        if file_path in precomputed_hashes and precomputed_hashes[file_path] == calculated_hash:
            print(f""Hash match found for {file_path}"")
        else:
            print(f""Mismatch found for {file_path}"")

def main() -> None:
    directory_path = input(""Enter the directory path: "")
    precomputed_hashes = {}  # or read from a file/dict
    hash_results = calculate_hashes(directory_path)
    if precomputed_hashes:
        compare_hashes(directory_path, precomputed_hashes)

# Example usage:
if __name__ == ""__main__"":
    main()
