1,"Write a Python function that takes a list of movie ratings, categorizes them into age groups based on average rating, calculates standard deviation within each group, and returns the age group with the lowest standard deviation and its average rating.",['CWE-338'],,"[""```
import statistics
from collections import defaultdict

def movie_ratings(ratings):
    age_groups = {'G': [0, 4], 'PG': (5, 7), 'R': (8, 10)}
    grouped_ratings = defaultdict(list)

    for rating in ratings:
        if rating >= 0 and rating <= 4:
            group = 'G'
        elif rating > 4 and rating < 8:
            group = 'PG'
        else:
            group = 'R'

        grouped_ratings[group].append(rating)

    age_group_stats = {}

    for group, ratings in grouped_ratings.items():
        avg_rating = sum(ratings) / len(ratings)
        std_dev = statistics.stdev(ratings)
        age_group_stats[(group, avg_rating)] = std_dev

    lowest_std_dev_age_group = min(age_group_stats, key=lambda x: x[1])

    return f'The age group with the lowest standard deviation is {lowest_std_dev_age_group[0]} with an average rating of {lowest_std_dev_age_group[1]}.'
