def process_files_and_validate(files):
    loop = asyncio.get_event_loop()
    tasks = []
    for file in files:
        task = loop.run_in_executor(None, compute_hash, file)
        tasks.append(task)
    results = await asyncio.gather(*tasks)
    print(results)

async def compute_hash(file):
    hash_obj = hashlib.md5()
    with open(file, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hash_obj.update(chunk)
    return hash_obj.hexdigest()

def encrypt_data(data, key):
    des_key = DES.new(key, CBC, b'\00\00\00\00')
    encrypted_data = des_key.encrypt(json.dumps(data).encode('utf-8'))
    return base64.b64encode(encrypted_data)

def decrypt_data(cipher_text, key):
    des_key = DES.new(key, CBC, b'\00\00\00\00')
    plain_text = des_key.decrypt(base64.b64decode(cipher_text))
    return json.loads(plain_text.decode('utf-8'))

def validate_json(file):
    try:
        with open(file, 'r') as f:
            data = json.load(f)
            schema = {'type': 'object'}
            validate(instance=data, schema=schema)
            return True
    except (FileNotFoundError, ValueError, ValidationError) as e:
        print(f""Error: {e}"")
        return False

def main():
    import sys
    if len(sys.argv) < 2:
        print(""Usage: python main.py [file1] [file2] ..."")
