    files = sys.argv[1:]
    loop = asyncio.get_event_loop()
    tasks = []
    for file in files:
        task = loop.run_in_executor(None, validate_json, file)
        tasks.append(task)
    results = await asyncio.gather(*tasks)
    print(results)

if __name__ == '__main__':
