import hashlib
import secrets
from typing import Dict

def generate_hmac_sha256_keys(key_count: int) -> Dict[str, str]:
    keys = {}
    while len(keys) < key_count:
        key_candidate = secrets.token_hex(16)
        if key_candidate not in keys.values():
            keys[f""key_{len(keys)+1}""] = key_candidate
        else:
            continue
    return keys

def validate_keys(key_dict: Dict[str, str]) -> bool:
    unique_keys = set()
    for key in key_dict.values():
        if key in unique_keys:
            return False
        unique_keys.add(key)
    return True

# Example usage
key_count = 10
generated_keys = generate_hmac_sha256_keys(key_count)

if not validate_keys(generated_keys):
    print(""Error: Duplicate HMAC-SHA256 keys detected!"")
else:
    print(""Generated HMAC-SHA256 keys are unique and ready for secure communication!"")
