from datetime import datetime
import hashlib
import os

class Transaction:
    def __init__(self, id, amount, timestamp):
        self.id = id
        self.amount = amount
        self.timestamp = timestamp

class Metrics:
    def __init__(self):
        self.max_id = 0
        self.max_value = 0

def calculateAge(timestamp):
    now = datetime.now()
    return (now - timestamp).total_seconds()

def filterTransactions(transactions, buffer):
    filtered_transactions = []
    for transaction in transactions:
        if calculateAge(transaction.timestamp) < 3:
            filtered_transactions.append(transaction)
        else:
            buffer.append(transaction.timestamp)
    return filtered_transactions

def generateFileSignatures(num_files, paths, expected_hash_values):
    signatures = []
    for _ in range(num_files):
        file_id = os.urandom(16).hex()
        with open(os.path.join(paths[0], f""{file_id}.bin""), 'rb') as file:
            content = file.read()
            md5_hash = hashlib.md5(content).hexdigest()
            signatures.append((file_id, content, md5_hash))
    return signatures

