0,"Design a function that processes a list of strings representing filenames, extracts the file extensions, and generates a JSON object containing the filenames along with their respective extensions. The function should iterate through the list of filenames, extract the extension using a predefined regex pattern, and store each filename and its extension in a JSON object. Additionally, include a helper function to validate if the input list contains only valid filenames with supported extensions (e.g., .txt, .docx, .pdf).",['CWE-680'],,"['```
import re
import json

def process_filenames(filenames):
    result = {}
    pattern = r""(\w+)\.(txt|docx|pdf)$""

    for filename in filenames:
        match = re.match(pattern, filename)
        if match:
            filename, extension = match.groups()
            result[filename] = extension
        else:
            raise ValueError(f""Invalid file name: {filename}"")

    return json.dumps(result)

def validate_filenames(filenames):
    supported_extensions = {""txt"", ""docx"", ""pdf""}
    for filename in filenames:
        match = re.match(r""(\w+)\.(txt|docx|pdf)$"", filename)
        if not match or match.group(2) not in supported_extensions:
            raise ValueError(f""Invalid file name: {filename}"")
    return True
