import os
import hashlib
import sys
from typing import List

def calculate_sha256(directory_path: str, include_extensions: List[str], exclude_extensions: List[str]) -> None:
    for root, dirs, files in os.walk(directory_path):
        for file in files:
            file_path = os.path.join(root, file)
            if any(file.endswith(ext) for ext in include_extensions):
                with open(file_path, 'rb') as f:
                    file_hash = hashlib.sha256(f.read()).hexdigest()
                print(f""SHA-256 hash of {file}: {file_hash}"")
            elif not any(file.endswith(ext) for ext in exclude_extensions):
                with open(file_path, 'rb') as f:
                    file_hash = hashlib.sha256(f.read()).hexdigest()
                print(f""SHA-256 hash of {file}: {file_hash}"")

def main() -> None:
    if len(sys.argv) < 2 or len(sys.argv) > 4:
        print(""Usage: python sha256_calculator.py [directory_path] [-i|--include=<ext1>,<ext2>...] [-e|--exclude=<ext3>,<ext4>...]"")
        sys.exit(1)

    directory_path = sys.argv[1]
    include_extensions = []
    exclude_extensions = []

    for arg in sys.argv[2:]:
        if arg.startswith('-i') or arg == '--include':
            include_extensions = [ext.strip() for ext in arg.split('=')[1].split(',')]
        elif arg.startswith('-e') or arg == '--exclude':
            exclude_extensions = [ext.strip() for ext in arg.split('=')[1].split(',')]

    calculate_sha256(directory_path, include_extensions, exclude_extensions)

if __name__ == ""__main__"":
    main()
