class Library:
    def __init__(self):
        self.books = []

    def add_book(self, book: Book):
        if not any(b.id == book.id for b in self.books):
            if len(book.title) > 0 and 1900 <= book.publication_year <= datetime.now().year:
                self.books.append(book)
            else:
                print(""Invalid addition: title cannot be empty or publication year is out of range."")

