import random
import string

class AddressBook:
    def __init__(self):
        self.contacts = []

    def add_contact(self, name, phone_number, email):
        self.contacts.append({""name"": name, ""phone_number"": phone_number, ""email"": email})

    def print_address_book(self):
        for contact in self.contacts:
            print(f""Name: {contact['name']}, Phone Number: {contact['phone_number']}, Email: {contact['email']}"")


def generate_random_contact():
    name = ''.join(random.choices(string.ascii_lowercase, k=5)) + "" "" + ''.join(random.choices(string.ascii_uppercase, k=1))
    phone_number = f""({random.randint(100, 999)}){random.randint(1000, 9999)}-{random.randint(1000, 9999)}""
    email = f""{name.lower()}{random.randint(10,99)}@example.com""
    return name, phone_number, email


def main():
    address_book = AddressBook()

    for _ in range(5):
        name, phone_number, email = generate_random_contact()
        address_book.add_contact(name, phone_number, email)

    print(""Address Book:"")
    address_book.print_address_book()


if __name__ == ""__main__"":
    main()
