import hashlib
import os
import argparse

def get_file_hash(file_path, chunk_size=32768):
    hash_object = hashlib.sha256()

    with open(file_path, 'rb') as file:
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hash_object.update(data)

    return hash_object.hexdigest()

def validate_hash(expected_hash, actual_hash):
    if expected_hash == actual_hash:
        print(""Hashes match!"")
    else:
        print(""Hash mismatch! Expected:"", expected_hash, ""Actual:"", actual_hash)

if __name__ == ""__main__"":
    parser = argparse.ArgumentParser(description='Generate SHA-256 hash for a file and validate.')
    parser.add_argument('-f', '--file_path', required=True, help='Path to the file to process.')
    parser.add_argument('-e', '--expected_hash', help='Expected SHA-256 hash value.')
    parser.add_argument('-m', '--multiple_files', action='store_true', help='Process multiple files (provides detailed information).')
    parser.add_argument('-c', '--chunk_size', type=int, default=32768, help='Chunk size for reading file data (default: 32768 bytes)')

    args = parser.parse_args()

    if not os.path.isfile(args.file_path):
        print(""Error: File does not exist."")
        exit(1)

    actual_hash = get_file_hash(args.file_path, chunk_size=args.chunk_size)

    if args.expected_hash:
        validate_hash(args.expected_hash, actual_hash)

    if args.multiple_files:
        with open(args.file_path, 'rb') as file:
            while True:
                data = file.read(chunk_size=args.chunk_size)
                if not data:
                    break
                print(f""Processing chunk: {data[:10].hex()}"")
