import requests
from flask import Flask, jsonify, request
app = Flask(__name__)

# Default values for resources
default_resource = {
    ""id"": 0,
    ""name"": """",
    ""description"": """"
}

@app.route('/resources/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if request.is_json:
        resource_data = request.get_json()
        new_resource = {""id"": resource_id, **resource_data}
        return jsonify(new_resource), 200
    else:
        return jsonify({""message"": ""Invalid request format""}), 400

@app.route('/resources/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    requests.delete(f'http://localhost:5000/resources/{resource_id}')
    new_default_resource = default_resource.copy()
    new_default_resource[""id""] = resource_id
    return jsonify(new_default_resource), 200

if __name__ == '__main__':
    app.run(debug=True)
