import pickle
import os
import yaml
import json
from abc import ABC, abstractmethod


class SerializableObject(ABC):
    @abstractmethod
    def serialize_attributes(self) -> dict:
        pass


class CustomObject(SerializableObject):
    def __init__(self, attr1: str, attr2: int):
        self.attr1 = attr1
        self.attr2 = attr2

    def serialize_attributes(self) -> dict:
        return {""attr1"": self.attr1, ""attr2"": self.attr2}


def serialize_custom_object(custom_object: CustomObject, file_path: str):
    try:
        with open(file_path, 'wb') as f:
            pickle.dump(custom_object, f)
    except Exception as e:
        print(f""Error during serialization: {str(e)}"")


def deserialize_custom_object(file_path: str, version: int = 1) -> CustomObject | None:
    try:
        with open(file_path, 'rb') as f:
            serialized_obj = pickle.load(f)

            if isinstance(serialized_obj, CustomObject):
                return serialized_obj
            else:
                return None

    except FileNotFoundError:
        print(""File not found"")
        return None
    except Exception as e:
        print(f""Error during deserialization: {str(e)}"")
        return None


def load_config(file_path: str) -> dict:
    if file_path.endswith('.yaml'):
        with open(file_path, 'r') as f:
            config = yaml.safe_load(f)
    elif file_path.endswith('.json'):
        with open(file_path, 'r') as f:
            config = json.load(f)
    else:
        raise ValueError(""Invalid file type"")

    return config


def check_for_changes(obj: CustomObject, serialized_obj: dict) -> bool:
    if serialized_obj[""attr1""] != obj.attr1 or serialized_obj[""attr2""] != obj.attr2:
        return True
    return False


def serialize_with_diff(obj: CustomObject, file_path: str):
    try:
        with open(file_path, 'rb') as f:
            serialized_obj = pickle.load(f)

        if isinstance(serialized_obj, dict) and ""attr1"" in serialized_obj and ""attr2"" in serialized_obj:
            if check_for_changes(obj, serialized_obj):
                serialized_obj[""attr1""] = obj.attr1
                serialized_obj[""attr2""] = obj.attr2

                with open(file_path, 'wb') as f:
                    pickle.dump(serialized_obj, f)
    except FileNotFoundError:
        print(""File not found"")
    except Exception as e:
        print(f""Error during serialization: {str(e)}"")


def deserialize_and_cache(obj: CustomObject, file_path: str):
    try:
        with open(file_path, 'rb') as f:
            serialized_obj = pickle.load(f)

        if isinstance(serialized_obj, dict) and ""attr1"" in serialized_obj and ""attr2"" in serialized_obj:
            return serialized_obj
        else:
            return None

    except FileNotFoundError:
        print(""File not found"")
        return None
    except Exception as e:
        print(f""Error during deserialization: {str(e)}"")
        return None


def cache_serialized_objects(cache_path: str):
    try:
        with open(cache_path, 'rb') as f:
            serialized_cache = pickle.load(f)
    except FileNotFoundError:
        print(""Cache file not found"")
        return {}

    return serialized_cache


def save_cache(serialized_cache: dict, cache_path: str):
    try:
        with open(cache_path, 'wb') as f:
            pickle.dump(serialized_cache, f)
    except Exception as e:
        print(f""Error during caching: {str(e)}"")
