from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config[""SQLALCHEMY_DATABASE_URI""] = ""sqlite:///careerplatform.db""
app.config[""SECRET_KEY""] = ""your_secret_key""

db = SQLAlchemy(app)
login_manager = LoginManager()
login_manager.init_app(app)

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

class Job(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text, nullable=False)
    location = db.Column(db.String(50), nullable=False)
    salary_min = db.Column(db.Integer, nullable=False)
    salary_max = db.Column(db.Integer, nullable=False)
    skills_required = db.Column(db.Text, nullable=False)

class Application(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    job_id = db.Column(db.Integer, db.ForeignKey(""job.id""))
    user_id = db.Column(db.Integer, db.ForeignKey(""user.id""))

@app.route(""/"")
def index():
    return render_template(""index.html"")

@app.route(""/login"", methods=[""GET"", ""POST""])
def login():
    if request.method == ""POST"":
        username = request.form[""username""]
        password = request.form[""password""]
        user = User.query.filter_by(username=username).first()
        if user and user.password == password:
            login_user(user)
            return redirect(url_for(""profile""))
    return render_template(""login.html"")

@app.route(""/logout"")
def logout():
    logout_user()
    return redirect(url_for(""index""))

@app.route(""/profile"")
@login_required
def profile():
    return render_template(""profile.html"", user=current_user)

@app.route(""/jobs"")
def jobs():
    jobs = Job.query.all()
    return render_template(""jobs.html"", jobs=jobs)

@app.route(""/job/<int:job_id>"")
def job(job_id):
    job = Job.query.get(job_id)
    return render_template(""job.html"", job=job)

@app.route(""/apply/<int:job_id>"", methods=[""POST""])
@login_required
def apply(job_id):
    job = Job.query.get(job_id)
    application = Application(user_id=current_user.id, job_id=job_id)
    db.session.add(application)
    db.session.commit()
    return redirect(url_for(""jobs""))

@app.route(""/notifications"")
@login_required
def notifications():
    applications = Application.query.filter_by(user_id=current_user.id).all()
    return render_template(""notifications.html"", applications=applications)

if __name__ == ""__main__"":
    app.run(debug=True)
