def generate_new_dict(original_dict, num_keywords, keyword_list):
    new_dict = {}
    keyword_count = 0
    next_keyword = None

    for key, value in original_dict.items():
        if keyword_count < num_keywords and any(keyword == key for keyword in keyword_list):
            new_dict[key] = value
            if keyword_count == num_keywords - 1:
                next_keyword = new_dict.copy()
            keyword_count += 1

