import os
from pydub import AudioSegment
from pydub.exceptions import CokedException

def convert_mp3_to_ogg(input_dir, output_dir):
    for root, dirs, files in os.walk(input_dir):
        for file in files:
            if file.endswith("".mp3""):
                mp3_file = os.path.join(root, file)
                ogg_filename = os.path.join(output_dir, f""{os.path.splitext(file)[0]}.ogg"")

                try:
                    sound = AudioSegment.from_mp3(mp3_file)
                    sound.export(ogg_filename, format=""OGG"")
                except CokedException as e:
                    print(f""Error converting {file}: {str(e)}"")

if __name__ == ""__main__"":
    input_dir = input(""Enter the directory location: "")
    output_dir = input(""Enter the target folder: "")

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    convert_mp3_to_ogg(input_dir, output_dir)
